import { PUNCH_IDS, type PunchId } from "./punches.ts";

/**
 * Two cue styles:
 *
 * - "tones": synthesised in the browser with the Web Audio API.
 *     Jab            one short high beep
 *     Cross          two quick mid beeps
 *     Left Hook      rising sweep
 *     Right Hook     falling sweep
 *     Left Uppercut  one low buzz
 *     Right Uppercut two low buzzes
 *   All finish within ~0.25 s.
 *
 * - "voice": short shouted call-outs ("Jab!", "Left hook!") bundled as local
 *   WAV files in public/audio/voice (generated by scripts/generate-voice.mjs).
 *   They are fetched once when the page loads and decoded into memory, so
 *   playback never touches the network during a session.
 *
 * A combination plays its punches back to back. Set bells and the 10-second
 * warning are synthesised.
 *
 * All playback is scheduled on the AudioContext clock at a given time in the
 * performance.now() timebase, so calls can be queued ahead of time.
 */
export type CueStyle = "tones" | "voice";
export type Signal = "setStart" | "setEnd" | "warning";

export function isCueStyle(value: unknown): value is CueStyle {
  return value === "tones" || value === "voice";
}

interface Tone {
  /** Offset from cue start (s). */
  at: number;
  duration: number;
  fromHz: number;
  toHz: number;
  wave: OscillatorType;
}

const CUE_PATTERNS: Record<PunchId, Tone[]> = {
  jab: [{ at: 0, duration: 0.11, fromHz: 1480, toHz: 1480, wave: "sine" }],
  cross: [
    { at: 0, duration: 0.07, fromHz: 880, toHz: 880, wave: "sine" },
    { at: 0.13, duration: 0.07, fromHz: 880, toHz: 880, wave: "sine" },
  ],
  leftHook: [{ at: 0, duration: 0.22, fromHz: 450, toHz: 1500, wave: "triangle" }],
  rightHook: [{ at: 0, duration: 0.22, fromHz: 1500, toHz: 450, wave: "triangle" }],
  leftUppercut: [{ at: 0, duration: 0.17, fromHz: 196, toHz: 196, wave: "square" }],
  rightUppercut: [
    { at: 0, duration: 0.08, fromHz: 196, toHz: 196, wave: "square" },
    { at: 0.14, duration: 0.08, fromHz: 196, toHz: 196, wave: "square" },
  ],
};

/** Rough loudness balancing between waveforms (square waves sound much louder). */
const WAVE_GAIN: Record<OscillatorType, number> = {
  sine: 0.8,
  triangle: 0.8,
  square: 0.28,
  sawtooth: 0.3,
  custom: 0.5,
};

const ATTACK_S = 0.005;
const RELEASE_S = 0.02;
/** Pause between punches inside a combination. */
const COMBO_GAP_S = { tones: 0.14, voice: 0.04 } as const;
/** Voice clips are trimmed to the part above this level so combos flow. */
const TRIM_THRESHOLD = 0.03;

const VOICE_URL = (id: PunchId) => `/audio/voice/${id}.wav`;

type AudioContextCtor = typeof AudioContext;

interface VoiceClip {
  buffer: AudioBuffer;
  /** Audible region (s). */
  offset: number;
  duration: number;
}

let ctx: AudioContext | null = null;
const activeSources = new Set<AudioScheduledSourceNode>();
let noiseBuffer: AudioBuffer | null = null;

let voiceFiles: Promise<Record<PunchId, ArrayBuffer>> | null = null;
let voiceClips: Record<PunchId, VoiceClip> | null = null;
let voiceDecoding: Promise<void> | null = null;

/** Pairs a performance.now() reading with the audio clock, to map between them. */
let clockAnchor: { wallMs: number; audioS: number } | null = null;

function getAudioContextCtor(): AudioContextCtor | null {
  if (typeof window === "undefined") return null;
  const w = window as Window & { webkitAudioContext?: AudioContextCtor };
  return window.AudioContext ?? w.webkitAudioContext ?? null;
}

export class AudioUnavailableError extends Error {}

/** Starts downloading the voice clips. Call once when the page loads. */
export function preloadVoice(): Promise<Record<PunchId, ArrayBuffer>> {
  if (!voiceFiles) {
    voiceFiles = Promise.all(
      PUNCH_IDS.map(async (id) => {
        const res = await fetch(VOICE_URL(id));
        if (!res.ok) throw new Error(`Failed to load ${id} voice clip`);
        return [id, await res.arrayBuffer()] as const;
      }),
    ).then((entries) => Object.fromEntries(entries) as Record<PunchId, ArrayBuffer>);
    // Allow a retry after a failed download.
    voiceFiles.catch(() => {
      voiceFiles = null;
    });
  }
  return voiceFiles;
}

function trim(buffer: AudioBuffer): VoiceClip {
  const data = buffer.getChannelData(0);
  let a = 0;
  let b = data.length - 1;
  while (a < b && Math.abs(data[a]) < TRIM_THRESHOLD) a++;
  while (b > a && Math.abs(data[b]) < TRIM_THRESHOLD) b--;
  const pad = Math.round(buffer.sampleRate * 0.01);
  a = Math.max(0, a - pad);
  b = Math.min(data.length - 1, b + pad);
  return { buffer, offset: a / buffer.sampleRate, duration: (b - a + 1) / buffer.sampleRate };
}

/** Decodes the voice clips into the audio context (once). */
function ensureVoiceDecoded(audio: AudioContext): Promise<void> {
  if (voiceClips) return Promise.resolve();
  if (!voiceDecoding) {
    voiceDecoding = preloadVoice()
      .then(async (files) => {
        const entries = await Promise.all(
          // decodeAudioData detaches its input, so decode a copy.
          PUNCH_IDS.map(async (id) => [id, trim(await audio.decodeAudioData(files[id].slice(0)))] as const),
        );
        voiceClips = Object.fromEntries(entries) as Record<PunchId, VoiceClip>;
      })
      .finally(() => {
        voiceDecoding = null;
      });
  }
  return voiceDecoding;
}

/** Prepares voice clips if audio is already unlocked (e.g. style switched mid-session). */
export function prepareVoice(): void {
  if (ctx) void ensureVoiceDecoded(ctx).catch(() => {});
}

function anchorClock(audio: AudioContext): void {
  clockAnchor = { wallMs: performance.now(), audioS: audio.currentTime };
}

/**
 * Creates/resumes the AudioContext and, for the voice style, makes sure the
 * clips are ready. Must be called from a user gesture (Start, Resume,
 * preview) to satisfy mobile autoplay restrictions.
 */
export async function unlockAudio(style: CueStyle): Promise<void> {
  const Ctor = getAudioContextCtor();
  if (!Ctor) throw new AudioUnavailableError("This browser does not support Web Audio.");

  // iOS Safari 16.4+: route Web Audio as media playback so the ring/silent
  // switch does not mute cues.
  const nav = navigator as Navigator & { audioSession?: { type: string } };
  if (nav.audioSession) {
    try {
      nav.audioSession.type = "playback";
    } catch {
      /* not supported, ignore */
    }
  }

  if (!ctx || ctx.state === "closed") ctx = new Ctor();
  const audio = ctx;

  if (audio.state !== "running") {
    // Play a one-sample silent buffer synchronously inside the gesture;
    // older iOS versions require this to unlock output.
    const buffer = audio.createBuffer(1, 1, 22050);
    const src = audio.createBufferSource();
    src.buffer = buffer;
    src.connect(audio.destination);
    src.start(0);
    await audio.resume();
  }
  if ((audio.state as string) !== "running") {
    throw new AudioUnavailableError("The browser blocked audio playback. Tap Start or Resume again.");
  }
  anchorClock(audio);

  if (style === "voice") {
    try {
      await ensureVoiceDecoded(audio);
    } catch {
      throw new AudioUnavailableError("Couldn't load the voice clips. Check your connection and try again, or use Tones.");
    }
  }
}

/**
 * True if the audio clock fell behind real time since the last unlock, which
 * means the device suspended audio (e.g. iOS in the background) and queued
 * calls are now stale.
 */
export function audioWasSuspended(): boolean {
  if (!ctx || !clockAnchor) return false;
  if (ctx.state !== "running") return true;
  const wallElapsed = performance.now() - clockAnchor.wallMs;
  const audioElapsed = (ctx.currentTime - clockAnchor.audioS) * 1000;
  return wallElapsed - audioElapsed > 1000;
}

/** Converts a performance.now() time to AudioContext time (never in the past). */
function audioTimeFor(audio: AudioContext, atMs: number): number {
  return audio.currentTime + Math.max(0, (atMs - performance.now()) / 1000) + 0.005;
}

function voiceReady(style: CueStyle): boolean {
  if (style === "voice" && !voiceClips) prepareVoice();
  return style === "voice" && voiceClips !== null;
}

function punchDurationS(id: PunchId, voice: boolean): number {
  if (voice) return voiceClips![id].duration;
  return Math.max(...CUE_PATTERNS[id].map((t) => t.at + t.duration));
}

/** Total duration (ms) of the call for these punches in the given style. */
export function cueDuration(punches: PunchId[], style: CueStyle): number {
  const voice = voiceReady(style);
  const gap = voice ? COMBO_GAP_S.voice : COMBO_GAP_S.tones;
  const s = punches.reduce((sum, id, i) => sum + punchDurationS(id, voice) + (i > 0 ? gap : 0), 0);
  return Math.round(s * 1000);
}

/**
 * Schedules the call for one punch or a combination at `atMs`
 * (performance.now() timebase). Returns false (without playing) if the audio
 * context is not running, e.g. after the OS interrupted audio. If voice clips
 * are not decoded yet, falls back to tones.
 */
export function playCue(punches: PunchId[], style: CueStyle, atMs: number = performance.now()): boolean {
  if (!ctx || ctx.state !== "running") {
    void ctx?.resume().catch(() => {});
    return false;
  }
  const voice = voiceReady(style);
  const gap = voice ? COMBO_GAP_S.voice : COMBO_GAP_S.tones;
  let t = audioTimeFor(ctx, atMs);
  for (const id of punches) {
    if (voice) {
      const clip = voiceClips![id];
      const src = ctx.createBufferSource();
      src.buffer = clip.buffer;
      src.connect(ctx.destination);
      track(src);
      src.start(t, clip.offset, clip.duration);
    } else {
      for (const tone of CUE_PATTERNS[id]) scheduleTone(ctx, tone, t);
    }
    t += punchDurationS(id, voice) + gap;
  }
  return true;
}

/** Schedules a set bell (start: one ring, end: three rings) or the 10-second warning clap. */
export function playSignal(kind: Signal, atMs: number = performance.now()): void {
  if (!ctx || ctx.state !== "running") return;
  const t = audioTimeFor(ctx, atMs);
  if (kind === "setStart") bell(ctx, t);
  else if (kind === "setEnd") for (let i = 0; i < 3; i++) bell(ctx, t + i * 0.35);
  else for (let i = 0; i < 2; i++) clap(ctx, t + i * 0.16);
}

function track(node: AudioScheduledSourceNode): void {
  activeSources.add(node);
  node.addEventListener("ended", () => {
    activeSources.delete(node);
    node.disconnect();
  });
}

function scheduleTone(audio: AudioContext, tone: Tone, cueStart: number): void {
  const t0 = cueStart + tone.at;
  const t1 = t0 + tone.duration;
  const peak = WAVE_GAIN[tone.wave];

  const osc = audio.createOscillator();
  osc.type = tone.wave;
  osc.frequency.setValueAtTime(tone.fromHz, t0);
  if (tone.toHz !== tone.fromHz) osc.frequency.exponentialRampToValueAtTime(tone.toHz, t1);

  // Short attack/release envelope prevents clicks.
  const gain = audio.createGain();
  gain.gain.setValueAtTime(0, t0);
  gain.gain.linearRampToValueAtTime(peak, t0 + ATTACK_S);
  gain.gain.setValueAtTime(peak, Math.max(t0 + ATTACK_S, t1 - RELEASE_S));
  gain.gain.linearRampToValueAtTime(0, t1);

  osc.connect(gain).connect(audio.destination);
  osc.addEventListener("ended", () => gain.disconnect());
  track(osc);
  osc.start(t0);
  osc.stop(t1 + 0.01);
}

/** Boxing-bell strike: inharmonic partials with long exponential decays. */
const BELL_PARTIALS = [
  { ratio: 1, gain: 0.35, decay: 1.6 },
  { ratio: 2.0, gain: 0.18, decay: 1.1 },
  { ratio: 2.76, gain: 0.2, decay: 0.9 },
  { ratio: 5.4, gain: 0.1, decay: 0.45 },
  { ratio: 8.93, gain: 0.05, decay: 0.25 },
];
const BELL_HZ = 760;

function bell(audio: AudioContext, t: number): void {
  for (const p of BELL_PARTIALS) {
    const osc = audio.createOscillator();
    osc.frequency.value = BELL_HZ * p.ratio;
    const g = audio.createGain();
    g.gain.setValueAtTime(0, t);
    g.gain.linearRampToValueAtTime(p.gain, t + 0.003);
    g.gain.exponentialRampToValueAtTime(0.0001, t + p.decay);
    osc.connect(g).connect(audio.destination);
    osc.addEventListener("ended", () => g.disconnect());
    track(osc);
    osc.start(t);
    osc.stop(t + p.decay + 0.05);
  }
}

/** Wooden clap: a short band-passed noise burst. */
function clap(audio: AudioContext, t: number): void {
  if (!noiseBuffer || noiseBuffer.sampleRate !== audio.sampleRate) {
    noiseBuffer = audio.createBuffer(1, Math.round(audio.sampleRate * 0.1), audio.sampleRate);
    const d = noiseBuffer.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  }
  const src = audio.createBufferSource();
  src.buffer = noiseBuffer;
  const bp = audio.createBiquadFilter();
  bp.type = "bandpass";
  bp.frequency.value = 1900;
  bp.Q.value = 4;
  const g = audio.createGain();
  g.gain.setValueAtTime(1.4, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + 0.06);
  src.connect(bp).connect(g).connect(audio.destination);
  src.addEventListener("ended", () => {
    bp.disconnect();
    g.disconnect();
  });
  track(src);
  src.start(t);
  src.stop(t + 0.08);
}

/** Immediately silences anything sounding or scheduled. */
export function stopAllCues(): void {
  for (const node of activeSources) {
    try {
      node.stop();
    } catch {
      /* already stopped */
    }
  }
  activeSources.clear();
}
